SELECT 'spor', 'spor.gundemi.org', 'spor.fix.tc', NULL, 'Spor Gündemi',
       'Futbol, basketbol, voleybol ve tüm branşlarda güncel spor haberleri — Süper Lig puan durumu, engelli sporları, amatör spor.',
       $c${"email": "spor@gundemi.org", "phone": "0532 229 18 92", "address": "Sağlık Mah. Aksu Cad. 13/5 Çankaya - Ankara"}$c$,
       $l${"frontend": "php", "phpTheme": true, "hmYsKunye": {"lead": "spor.gundemi.org — sporun nabzı burada atar.", "email": "spor@gundemi.org", "phone": "0532 229 18 92", "tuzel": "Tükav Gaziler Eğitim Kültür Hizmetleri Ltd. Şti.", "yayin": "SPOR GÜNDEMİ", "address": "Sağlık Mah. Aksu Cad. 13/5 Çankaya - Ankara", "genelMudur": "Nail Türkoğlu", "yaziIsleri": "Melek Acar", "yayinIlkeleri": "İlkeli, iffetli ve isabetli habercilik: başlık, özet ve kaynak bağlantısıyla sınırlı besleme kayıtlarını olduğu gibi gösterir. Tam metin, kaynağın kendi sayfasındadır. Editörün yazdığı haberler bu sitede yayımlanır.", "yayinYonetmeni": "Mustafa ÖZDEMİR"}, "hmVitrinTheme": "yenisafak", "hmFooterAboutHtml": "<p>TÜRKATA HABER AJANSI, Türk Kültürünü Araştırma ve Tanıtma Vakfı’nın haber ajansıdır. 1998’den bu yana yerel yönetimler, kamu kurumları ile sivil toplum ve sektör gündemini Türkçe olarak kamuoyuna aktarır.</p>\n<p>Yerelin Sesini Geleceğe Taşıyan Güvenilir Haber Ağı.</p>\n<h2 id=\"yayin-ilkeleri\">Yayın ilkeleri</h2>\n<p>Ajans, başlık, özet ve kaynak bağlantısıyla sınırlı besleme kayıtlarını olduğu gibi gösterir. Tam metin, kaynağın kendi sayfasındadır. Editörün yazdığı haberler bu sitede yayımlanır.</p>", "hmLayoutSanitizeRev": "hm-layout-sanitize-20260727a", "hmNewsFooterEnabled": true, "hmNewsSliderEnabled": true, "hmSehitSearchEnabled": false, "hmSiteRssDefaultsRev": "20260727site1", "hmTepeMansetOptInRev": "tepe-manset-default-on-v2", "hmNewsYsMansetEnabled": true, "hmNewsYsTickerEnabled": true, "hmRssKarmaDefaultsRev": "rss-karma-default-v1", "hmNewsYsAuthorsEnabled": true, "hmNewsYsGalleryEnabled": true, "hmNewsHeaderMenuEnabled": true, "hmNewsTepeMansetEnabled": true, "hmNewsYsMostReadEnabled": true, "hmNewsYsVideoBandEnabled": true, "hmNewsBreakingBandEnabled": true, "sadeNewsAtaturkBandEnabled": false, "hmNewsYsSideHeadlinesEnabled": true, "hmCorporateWarsSectionEnabled": false, "hmNewsCategorySectionsEnabled": true, "hmNewsYsCategoryBlocksEnabled": true, "hmCorporateAtaturkCornerEnabled": false, "hmCorporateCulturePortalBandEnabled": false, "hmCorporateNationalDaysSectionEnabled": false, "sadeNewsHistoryNationalDaysBandEnabled": false, "hmSiteKind": "news", "logoUrl": "/gundemi/logos/spor-gundemi.png", "faviconUrl": "/gundemi/logos/spor-gundemi.png", "hmYsSlogan": "Sporun nabzı burada atar.", "hmPrimaryColor": "#0b5a32", "hmSecondaryColor": "#d71920", "hmYsMansetPreset": "takvim", "hmNewsYsMansetLayout": "takvim", "showPlatformNav": false, "hybridRssEnabled": false, "hmCatTree": "spor", "hmConceptSite": true, "hmConceptTopic": "spor", "hmNewsYsStandingsEnabled": true, "hmNewsYsSportsHoroscopeEnabled": true, "hmNewsYsHoroscopeEnabled": false, "hmNewsRssSources": [230], "hmNewsRssCategoryOnly": ["spor", "futbol", "basketbol", "voleybol", "hentbol", "gures", "atletizm", "tenis", "yuzme", "motor-sporlari", "dovus-sporlari", "e-spor", "amator-spor", "engelli-sporlari"], "hmNavOnlyCategorySlugs": ["spor", "futbol", "basketbol", "voleybol", "hentbol", "gures", "atletizm", "tenis", "yuzme", "motor-sporlari", "dovus-sporlari", "e-spor", "amator-spor", "engelli-sporlari", "ozel-haber"], "hmCategorySortSlugs": ["spor", "futbol", "basketbol", "voleybol", "hentbol", "gures", "atletizm", "tenis", "yuzme", "motor-sporlari", "dovus-sporlari", "e-spor", "amator-spor", "engelli-sporlari"], "hmCorporateMenuItems": [{"id": "m1", "label": "Spor", "href": "/kategori/spor", "parentId": "", "enabled": true}, {"id": "m2", "label": "Futbol", "href": "/kategori/futbol", "parentId": "", "enabled": true}, {"id": "m3", "label": "Basketbol", "href": "/kategori/basketbol", "parentId": "", "enabled": true}, {"id": "m4", "label": "Voleybol", "href": "/kategori/voleybol", "parentId": "", "enabled": true}, {"id": "m5", "label": "Hentbol", "href": "/kategori/hentbol", "parentId": "", "enabled": true}, {"id": "m6", "label": "Güreş", "href": "/kategori/gures", "parentId": "", "enabled": true}, {"id": "m7", "label": "Atletizm", "href": "/kategori/atletizm", "parent